runsAfter.command:
python3 -c "
import json
for l in open('journal.jsonl'):
    j=json.loads(l)
    if j.get('type') in ('started','log'): print(j.get('type'), j.get('label') or j.get('message'))
    if j.get('type')=='result': print('RESULT', str(j.get('result'))[:400].replace('\n',' '))
" | tail -12; cd ~/hunkproof && git log --oneline | head -5; ls src test; npm test 2>&1 | tail -5

cd ~/hunkproof && node --test test/runs.test.js test/transcript.test.js 2>&1 | grep -E "^not ok|^# (pass|fail)|error:|expected|actual" | head -40; node --input-type=module -e "
import { classifyRun, parseOutcome } from './src/runs.js';
const c = (s) => { const r = classifyRun(s); console.log(JSON.stringify(s).slice(0,70), '=>', r.isRun, r.runner, r.silentOk); };
c(\"grep -A6 -E '^== (script|node|npm|node:test|vitest|make|prettier|pytest|ruff|eslint)\$' f | cut -c1-330\");
c('grep -n \"VITEST_MAX_WORKERS\\\\|vitest run\\\\|npm run test\" scripts/verify.sh | head; docker ps');
c(\"ssh root@[REDACTED:ip] 'cd /root/My-App && nohup ./deploy.sh > /tmp/deploy-34.log 2>&1 &' ; echo launched\");
c('node bin/hunkproof.js --pr 1 --repo ~/hunkproof');
c('npx hunkproof --pr 1'); c('./bin/hunkproof.js');
c('bash scripts/verify.sh > /tmp/v.log 2>&1; echo exit \$?; grep x /tmp/v.log | tail -15');
c('npx tsc --noEmit'); c('npx tsc --noEmit 2>&1 | tail -5'); c('cd /r && npx tsc --noEmit 2>&1'); c('bash scripts/verify.sh');
c('(npx tsc --noEmit -p . 2>&1 | tail -5; echo TSC_DONE) & (npx eslint lib/a.ts 2>&1 | tail -5)');
c('npx vitest run 2>&1 | grep -E \"Tests \"; npx tsc --noEmit 2>&1 | grep -c \"error TS\"');
console.log(parseOutcome('script','','',false), parseOutcome('script','','',false,{silentPass:false}));
"

cd ~/hunkproof && node --test --test-name-pattern="post the comment through gh" test/cli.test.js 2>&1 | grep -vE "^\s+(duration_ms|type|\.\.\.|---)" | sed -n 1,60p; echo ======; node --input-type=module -e "
