ev.hunks=big; const md=renderMarkdown(ev); console.log(md.length, (md.match(/xxxxxxxxxx/g)||[]).length); console.log(md.split('\n').filter(l=>l.includes('xxxx')).slice(0,2).map(l=>l.slice(0,200)));
"

